
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_x_cam_s12h_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_x_cam_s12h", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.191042496100065e+00, -3.128838075297443e+00, -3.041956714522601e+00, -2.922212990084612e+00, -2.760366620381111e+00, -2.547793941203161e+00, -2.279930538399476e+00, -1.960667353300557e+00, -1.602075355929616e+00, -1.214381398344661e+00, -8.052018363293060e-01, -5.079430101026707e-01, -4.274686931787607e-01, -3.503907956879688e-01, -2.583670692394404e-01, -1.663981906189906e-01, -8.698792392016857e-02, -3.113397061966538e-02, -6.752429748400373e-03, -7.593037584514081e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


